"""Central metric glossary used by documentation and Streamlit help controls."""
from __future__ import annotations
from dataclasses import dataclass

@dataclass(frozen=True)
class MetricDefinition:
    metric_id:str; label:str; short_description:str; unit:str; why_it_matters:str; calculation:str; interpretation:str; relationships:tuple[str,...]=(); caveats:str=""

def _m(i,l,d,u,w,c,it,r=(),cv=""):return MetricDefinition(i,l,d,u,w,c,it,r,cv)

