def get_metric(metric_id:str)->MetricDefinition:
    try:return METRICS[metric_id]
    except KeyError as e:raise KeyError(f"Unknown metric_id: {metric_id}") from e

def validate_metric_registry()->None:
    for metric_id,m in METRICS.items():
        if m.metric_id!=metric_id:raise ValueError(f"Metric key/id mismatch: {metric_id}")
        required=(m.label,m.short_description,m.unit,m.why_it_matters,m.calculation,m.interpretation)
        if any(not x.strip() for x in required):raise ValueError(f"Metric {metric_id} has an empty required field.")
        missing=set(m.relationships)-set(METRICS)
        if missing:raise ValueError(f"Metric {metric_id} references unknown metrics: {sorted(missing)}")
